/*!
 * timeline-date-fix.js — renders the Education & Experience stamp date in the
 * page's own calendar and format.
 *
 * WHY THIS EXISTS
 * kdcv-resume-entry-fix.js is generated by the background tooling and injects
 * the "National Open-Source AI Platform" row with `date: "1405/12/24"` on ALL
 * nine locales. That value is correct — it is the Solar Hijri (Shamsi) start
 * date — but shipping the raw Shamsi stamp to an English, German or Japanese
 * page put a Persian-calendar date next to Gregorian ones on the same page.
 *
 * So the stamp is parsed and re-rendered through Intl using the same
 * locale/calendar map linkedin-content.js already uses site-wide: Persian
 * pages keep the Persian calendar, everything else gets the Gregorian
 * equivalent in its own language's format.
 *
 * That generated file is rewritten by the tooling, so the correction lives
 * here instead, in a file the tooling does not own.
 */
(function () {
  "use strict";

  if (window.__KDCV_TIMELINE_DATE__) return;
  window.__KDCV_TIMELINE_DATE__ = true;

  /* Same map as linkedin-content.js, so every date on the page agrees. */
  var CAL = {
    en: "en-US-u-ca-gregory",
    fa: "fa-IR-u-ca-persian",
    ar: "ar-SA-u-ca-gregory",
    de: "de-DE-u-ca-gregory",
    es: "es-ES-u-ca-gregory",
    fr: "fr-FR-u-ca-gregory",
    tr: "tr-TR-u-ca-gregory",
    zh: "zh-CN-u-ca-gregory",
    ja: "ja-JP-u-ca-gregory"
  };

  // A y/m/d stamp in Latin, Persian or Arabic-Indic digits.
  var STAMP = /^([۰-۹٠-٩\d]{4})\s*\/\s*([۰-۹٠-٩\d]{1,2})\s*\/\s*([۰-۹٠-٩\d]{1,2})$/;

  function toLatin(s) {
    return s.replace(/[۰-۹]/g, function (d) { return String(d.charCodeAt(0) - 1776); })
            .replace(/[٠-٩]/g, function (d) { return String(d.charCodeAt(0) - 1632); });
  }

  function locale() {
    var d = (document.documentElement.lang || "en").toLowerCase().split("-")[0];
    return CAL[d] ? d : "en";
  }

  /* Shamsi -> Gregorian. Rather than carry a conversion table, walk the
     Gregorian days around the expected window and ask Intl which one renders
     as the wanted Persian date — Intl owns the calendar rules, so this cannot
     drift from the browser's own formatting. The Persian year begins in the
     Gregorian year (y + 621), which bounds the search to ~14 months.
     Noon UTC avoids the timezone edge that would shift the day by one. */
  function fromShamsi(y, m, d) {
    var probe = new Intl.DateTimeFormat("en-u-ca-persian", {
      year: "numeric", month: "numeric", day: "numeric", timeZone: "UTC"
    });
    var start = Date.UTC(y + 620, 11, 1, 12);
    for (var i = 0; i < 500; i++) {
      var when = new Date(start + i * 86400000);
      var p = probe.formatToParts(when).reduce(function (a, x) { a[x.type] = x.value; return a; }, {});
      if (Number(toLatin(p.year)) === y && Number(p.month) === m && Number(p.day) === d) return when;
    }
    return null;
  }

  var cache = {};

  function render(y, m, d) {
    var loc = locale();
    var key = loc + "|" + y + "-" + m + "-" + d;
    if (cache[key]) return cache[key];

    var when = fromShamsi(y, m, d);
    if (!when) return null;

    try {
      cache[key] = new Intl.DateTimeFormat(CAL[loc], {
        year: "numeric", month: "long", day: "numeric", timeZone: "UTC"
      }).format(when);
    } catch (e) {
      return null;
    }
    return cache[key];
  }

  /* ---- <time datetime> elements -----------------------------------------
     The Certificates archive carries 73 `<time datetime="YYYY-MM-DD">` stamps
     whose visible text is hard-coded English ("Sep 20, 2023"). The machine
     value is the authority, so each one is re-rendered through the SAME
     locale/calendar map used above: a Persian visitor sees the Solar Hijri
     date, everyone else sees their own language's Gregorian format — the same
     instant, written the way that reader writes dates.

     The original English text is kept in `data-kdcv-src` so a language switch
     within the page (Certificates translates in place via ?lang=) can be
     re-applied without reloading, and `datetime` is never touched so the
     value machines read stays ISO-8601. */
  function renderISO(iso) {
    // Day precision (YYYY-MM-DD) and month precision (YYYY-MM) are both real
    // on this page — some credentials record only the month of issue. They are
    // formatted with the fields they actually carry, so a month-only stamp
    // never gains a day it did not have.
    var day = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || "");
    var month = day ? null : /^(\d{4})-(\d{2})$/.exec(iso || "");
    var m = day || month;
    if (!m) return null;

    var loc = locale();
    var key = "iso|" + loc + "|" + iso;
    if (cache[key]) return cache[key];

    // Noon UTC keeps the calendar conversion off the midnight boundary, where
    // a timezone offset would shift the rendered day by one.
    var when = Date.UTC(Number(m[1]), Number(m[2]) - 1, day ? Number(m[3]) : 15, 12);
    var opts = day
      ? { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" }
      : { year: "numeric", month: "long", timeZone: "UTC" };
    try {
      cache[key] = new Intl.DateTimeFormat(CAL[loc], opts).format(new Date(when));
    } catch (e) {
      return null;
    }
    return cache[key];
  }

  function fixTimes() {
    var nodes = document.querySelectorAll("time[datetime]");
    for (var i = 0; i < nodes.length; i++) {
      var node = nodes[i];
      var iso = node.getAttribute("datetime");
      if (!iso) continue;

      // Day or month precision. A bare year needs no localisation and a full
      // timestamp means something else, so both are left alone.
      if (!/^\d{4}-\d{2}(-\d{2})?$/.test(iso)) continue;

      if (!node.dataset.kdcvSrc) node.dataset.kdcvSrc = node.textContent.trim();

      var out = renderISO(iso);
      if (!out || node.textContent.trim() === out) continue;
      node.textContent = out;
      node.dataset.kdcvLoc = locale();
    }
  }

  /* ---- one format for the whole timeline ---------------------------------
     The stamps arrive from three different places — hand-authored in the nine
     HTML files, injected by the generated resume script, and converted from
     Shamsi by render() above — and each used its own shape. On one English
     page that produced, in a single column: "March 15, 2027", "2024 - Present",
     "2018 - 2023", "Jul 2018 - 2023", "Mar - Oct 2009". Mixed granularity in a
     column of dates reads as noise, and the widest of them overflowed the
     104px grid track, so the column was ragged as well as inconsistent.

     Year range is the only granularity every source can express, so that is
     the one they are all normalised to: "2015 – 2017", "2024 – اکنون". Digits
     and the "present" word come from the page's own locale, and the separator
     is an en dash with non-breaking spaces so a range never wraps mid-dash. */
  var PRESENT = {
    en: "Present", fa: "اکنون", ar: "الآن", de: "heute", es: "Actualidad",
    fr: "Aujourd’hui", tr: "Günümüz", zh: "至今", ja: "現在"
  };
  // Any locale's word for "now", so an already-correct stamp is recognised.
  var PRESENT_RE = /present|now|اکنون|الآن|heute|actualidad|aujourd|günümüz|至今|現在/i;

  function localDigits(n) {
    try {
      return new Intl.NumberFormat(CAL[locale()], { useGrouping: false }).format(n);
    } catch (e) {
      return String(n);
    }
  }

  function normalise(node) {
    var raw = (node.textContent || "").trim();
    if (!raw) return;

    var present = PRESENT_RE.test(raw) || node.dataset.kdcvOngoing === "1";
    // Years in any of the three digit sets this site renders.
    var years = (toLatin(raw).match(/\d{4}/g) || []).map(Number);
    var word = PRESENT[locale()] || PRESENT.en;

    var out;
    if (!years.length) {
      // "Now" on its own — a single-word stamp, nothing to range.
      out = present ? word : raw;
    } else {
      var start = years[0];
      var end = present ? word : localDigits(years[years.length - 1]);
      out = start === years[years.length - 1] && !present
        ? localDigits(start)
        : localDigits(start) + " – " + end;
    }

    if (out !== raw) node.textContent = out;
  }

  function fix() {
    fixTimes();
    var nodes = document.querySelectorAll(".timeline-date");
    for (var i = 0; i < nodes.length; i++) {
      var node = nodes[i];
      if (node.dataset.kdcvDate === "1") continue;

      var m = STAMP.exec((node.textContent || "").trim());
      if (m) {
        var out = render(Number(toLatin(m[1])), Number(toLatin(m[2])), Number(toLatin(m[3])));
        if (!out) continue;
        node.textContent = out;
        /* A bare Shamsi stamp is the START of a role that is still running —
           that is the only shape the generated script emits. Flagged here so
           normalise() renders it as an open range rather than a lone year,
           which is how the same row is authored on the Persian page. */
        node.dataset.kdcvOngoing = "1";
      }

      normalise(node);
      node.dataset.kdcvDate = "1";
    }
  }

  function init() {
    // The generated script injects its row after this one runs, so watch for
    // it rather than only correcting what is present at load.
    if ("MutationObserver" in window && document.body) {
      var queued = false;
      new MutationObserver(function () {
        if (queued) return;
        queued = true;
        // setTimeout, not rAF: rAF is paused while the tab is hidden.
        window.setTimeout(function () { queued = false; fix(); }, 60);
      }).observe(document.body, { childList: true, subtree: true });
    }

    fix();
    var tries = 0;
    var timer = window.setInterval(function () {
      fix();
      if (++tries >= 10) window.clearInterval(timer);
    }, 300);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
})();
